import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.G0y0PQA7.js";const n="/relio/shots/en/export-image-dialog.png",i="/relio/shots/en/export-text-mermaid.png",u=JSON.parse('{"title":"Export","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/export.md","filePath":"en/features/export.md"}'),s={name:"en/features/export.md"};function d(l,t,c,h,g,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h1><p>Excel, HTML, image, dictionary, translation dictionary, test data and Java exports; DBML, Mermaid, Markdown and model JSON exports; and page setup and printing. DDL has its own page: <a href="/relio/en/features/ddl">DDL</a>.</p><p>There is a short introduction in <a href="/relio/en/quick/export#other-exports">Generate and export DDL</a> in Quick start.</p><h2 id="export-menu" tabindex="-1">Export menu <a class="header-anchor" href="#export-menu" aria-label="Permalink to &quot;Export menu&quot;">​</a></h2><p>Choose from File › Export ▸ (canvas right-click › Document › Export ▸ is the same).</p><table tabindex="0"><thead><tr><th>Item</th><th>What it creates</th></tr></thead><tbody><tr><td>DDL…</td><td>SQL to run on a database — <a href="/relio/en/features/ddl">DDL</a></td></tr><tr><td>Excel…</td><td>Table documents (<code>.xlsx</code>)</td></tr><tr><td>HTML…</td><td>A static document bundle you can read offline</td></tr><tr><td>Image…</td><td>PNG · JPG · BMP · SVG pictures</td></tr><tr><td>Dictionary…</td><td>The word dictionary as CSV</td></tr><tr><td>Translation dictionary…</td><td>A file of physical name and logical name pairs</td></tr><tr><td>Test data…</td><td>INSERT SQL or DBUnit files</td></tr><tr><td>Java…</td><td>Java class sources (plain Java or JPA Entity)</td></tr><tr><td>DBML… · Mermaid… · Markdown document… · Model JSON…</td><td>Text formats for exchanging with other tools</td></tr></tbody></table><p>Common to all of them:</p><ul><li>Writing to an existing file asks whether to overwrite it.</li><li>When a file is created, a notice appears at the bottom right of the app window; <strong>Open folder</strong> opens the folder in File Explorer with that file selected.</li><li>If the output path stored in the document points outside the document&#39;s folder, Relio says &quot;The path stored in the file is outside the document folder.&quot; If you received the file from someone else, check that the path is right.</li><li>If there are warnings, their number is shown and they are kept in the problem list. Long exports can be stopped with <strong>Cancel</strong> in the progress window.</li></ul><h2 id="excel" tabindex="-1">Excel <a class="header-anchor" href="#excel" aria-label="Permalink to &quot;Excel&quot;">​</a></h2><ul><li><strong>Template</strong> — <strong>Built-in</strong> (Korean — table specification (default_ko) · English (default_en) · Japanese (default_ja) · Chinese (default_zh)), <strong>File</strong> (a template you pick), or a template registered in Settings › Excel template.</li><li>A user template is an <code>.xlsx</code> or ERMaster <code>.xls</code> with words and loops sheets and template sheets. The output is always <code>.xlsx</code>; if you choose <code>.xls</code>, it writes <code>.xlsx</code> instead.</li><li><strong>Category</strong> — All or a single category.</li><li><strong>Include the diagram picture</strong> · <strong>Use logical names as sheet names</strong>.</li><li>Tables, indexes and so on are created by copying the template sheets. Sheet names are shortened to 31 characters, and (1), (2)… are added when names repeat.</li></ul><p>To customize a built-in template, use <strong>Save to file…</strong> in Tools › Settings › Excel template, edit the file, and register it as a user template. <a href="/relio/en/features/preferences#excel-template">Settings › Excel template</a></p><h2 id="html" tabindex="-1">HTML <a class="header-anchor" href="#html" aria-label="Permalink to &quot;HTML&quot;">​</a></h2><p>Choose the <strong>Output folder</strong>, then <strong>Include the diagram image</strong> · <strong>Include category images</strong> · <strong>Open after saving (index.html)</strong>. It is a frameless static HTML bundle, so you can open the files directly and nothing connects to the internet. It includes the diagram, tables, columns and indexes.</p><h2 id="image" tabindex="-1">Image <a class="header-anchor" href="#image" aria-label="Permalink to &quot;Image&quot;">​</a></h2><ul><li>The format is chosen by the output file&#39;s extension (PNG, JPG, BMP, SVG).</li><li>The area around all elements is drawn at 100% zoom with a 10px margin on every side. If a side exceeds 16,384px, the image is scaled down and you are told.</li><li>Turn on <strong>Also output an image per category (displayed categories)</strong> to create a separate picture for each category. If <strong>Category folder</strong> is empty, they go into a <code>categories</code> folder next to the output file.</li><li><strong>Open the file after saving</strong>.</li></ul><p>Find and selection highlights are not included, and images always use light colors even with a dark theme.</p><figure class="shot" data-scene="export-image-dialog"><img src="'+n+'" alt="Image export dialog — the output file and the per-category image option" loading="lazy"><figcaption>Image export dialog — the output file and the per-category image option</figcaption></figure><h2 id="dictionary" tabindex="-1">Dictionary <a class="header-anchor" href="#dictionary" aria-label="Permalink to &quot;Dictionary&quot;">​</a></h2><p><strong>Export dictionary (CSV)</strong> — Exports the word dictionary as CSV. The columns are physical name, logical name, type and description. Turn on <strong>Add a UTF-8 BOM</strong> so non-ASCII text such as Korean is not garbled when you open the file directly in Excel.</p><h2 id="translation-dictionary" tabindex="-1">Translation dictionary <a class="header-anchor" href="#translation-dictionary" aria-label="Permalink to &quot;Translation dictionary&quot;">​</a></h2><p><strong>Export translation dictionary</strong> — Exports the model&#39;s physical and logical name pairs as a translation dictionary file (UTF-8, one <code>physical name,logical name</code> pair per line). Set the <strong>Dictionary name</strong> and <strong>Save location</strong> (<code>.txt</code> if there is no extension), and check in the preview how many entries are included. Entries that are left out are listed with the count and reason. The dictionary you create is used to fill logical names when importing from a database.</p><h2 id="test-data" tabindex="-1">Test data <a class="header-anchor" href="#test-data" aria-label="Permalink to &quot;Test data&quot;">​</a></h2><p>First create the data in Model › Test data…. <a href="/relio/en/features/model#test-data">Model menu › Test data</a></p><ul><li>Choose the <strong>Test data to export</strong>.</li><li><strong>Format</strong> — SQL (INSERT statements) · DBUnit XML · DBUnit Flat XML · DBUnit Excel (.xlsx).</li><li>Turn on <strong>One file per test data set (name.extension)</strong> to create a separate file for each data set.</li></ul><p>Values containing single quotes or empty values are written so they do not break the SQL.</p><h2 id="java" tabindex="-1">Java <a class="header-anchor" href="#java" aria-label="Permalink to &quot;Java&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Output folder</td><td>Package folders are created under it.</td></tr><tr><td>Package name</td><td>For example <code>com.example.model</code>. Relio tells you if it does not follow Java rules.</td></tr><tr><td>Class name suffix</td><td>For example <code>Entity</code>. Leave it empty for no suffix.</td></tr><tr><td>File encoding</td><td></td></tr><tr><td>Type</td><td><strong>Plain Java</strong> or <strong>JPA Entity</strong> (<code>@Entity</code> classes)</td></tr><tr><td>Output Hibernate mapping files (.hbm.xml)</td><td>Plain Java only. Not used with the JPA Entity format.</td></tr></tbody></table><p><strong>JPA options</strong> (when the type is JPA Entity):</p><ul><li><strong>Use javax.persistence (off: jakarta.persistence)</strong></li><li><strong>Use java.util.Date for dates (off: java.time)</strong></li><li><strong>Add child list fields to parents (@OneToMany)</strong></li><li><strong>Map foreign keys as value fields, not objects</strong></li></ul><h2 id="text-formats-dbml-mermaid-markdown-model-json" tabindex="-1">Text formats (DBML, Mermaid, Markdown, model JSON) <a class="header-anchor" href="#text-formats-dbml-mermaid-markdown-model-json" aria-label="Permalink to &quot;Text formats (DBML, Mermaid, Markdown, model JSON)&quot;">​</a></h2><p>Common fields:</p><ul><li><strong>Scope</strong> — All · Category · Selected tables (select them on the canvas first).</li><li><strong>Output file</strong> · <strong>Encoding</strong> · <strong>Use CRLF line endings (Windows)</strong>.</li><li><strong>Copy to clipboard</strong> — Paste the result without creating a file (DBML · Mermaid · Markdown).</li><li>Settings are remembered per file on this PC. The document (<code>.erm</code>) is not changed, so exporting does not mark it as changed.</li></ul><table tabindex="0"><thead><tr><th>Format</th><th>What it is</th><th>Format options</th></tr></thead><tbody><tr><td>DBML</td><td>The text format used by dbdiagram.io and other tools</td><td>Write column groups as TablePartial · Write notes as sticky notes</td></tr><tr><td>Mermaid</td><td>An <code>erDiagram</code> that GitHub, Notion and other tools render as a diagram</td><td>Use logical names as aliases · Wrap in a mermaid code block · Write one file per category</td></tr><tr><td>Markdown document</td><td>A schema document with a table of contents, a Mermaid diagram, and column, foreign key and index tables for each table</td><td>Include a Mermaid diagram · Include views · Include index and unique key tables · Tables only (no title, table of contents or diagram) · Group by category</td></tr><tr><td>Model JSON</td><td>The whole model as JSON — for connecting other tools</td><td>Include images (Base64) · Include change history · Exclude layout (position, size, color) · Include a timestamp</td></tr></tbody></table><p>Get the JSON Schema that describes the model JSON structure with the command-line <code>relio export json --print-schema</code>. <a href="/relio/en/features/cli#relio-export">Command line</a></p><figure class="shot" data-scene="export-text-mermaid"><img src="'+i+'" alt="Mermaid export dialog — scope, format options and Copy to clipboard" loading="lazy"><figcaption>Mermaid export dialog — scope, format options and Copy to clipboard</figcaption></figure><h2 id="printing" tabindex="-1">Printing <a class="header-anchor" href="#printing" aria-label="Permalink to &quot;Printing&quot;">​</a></h2><ul><li><strong>File › Page setup…</strong> — <strong>Orientation</strong> (landscape or portrait, landscape by default), <strong>Scale %</strong>, <strong>Paper size</strong> (A4 by default), and margins <strong>Top</strong> · <strong>Left</strong> · <strong>Right</strong> · <strong>Bottom</strong> (cm).</li><li><strong>File › Print…</strong> (<kbd>Ctrl</kbd>+<kbd>P</kbd>) — The print preview shows the page breaks and page count of the current view (All or a category); <strong>Print…</strong> sends it to the operating system&#39;s print dialog. You can also open <strong>Page setup…</strong> right from the preview.</li><li>Printing draws at the page setup scale and splits the diagram over several pages, left to right and top to bottom. It has a white background without the grid.</li><li>On the canvas, page boundaries are shown as light gray lines for each page size (they are not drawn in exports or printing).</li></ul>',37)])])}const f=e(s,[["render",d]]);export{u as __pageData,f as default};
